'use client';

import React, { useState } from 'react';
import {
  Chart as ChartJS,
  LineElement,
  BarElement,
  ArcElement,
  CategoryScale,
  LinearScale,
  Title,
  Tooltip,
  Legend,
  PointElement
} from 'chart.js';
import { Line, Bar, Doughnut } from 'react-chartjs-2';
import { CalendarIcon } from '@heroicons/react/24/outline';

// Register Chart.js components
ChartJS.register(
  LineElement,
  BarElement,
  ArcElement,
  PointElement,
  CategoryScale,
  LinearScale,
  Title,
  Tooltip,
  Legend
);

interface Macros {
  protein: number;
  carbs: number;
  fat: number;
}

interface DailyEntry {
  date: string;
  weight: number;        // lbs or kg
  workouts: string;      // textual description
  caloriesIn: number;
  caloriesOut: number;
  macros: Macros;        // protein, carbs, fat
}

export default function DashboardPage() {
  // Mock data stored in state
  const [dailyData] = useState<DailyEntry[]>([
    {
      date: '2025-03-01',
      weight: 180,
      workouts: '30 min strength training',
      caloriesIn: 2000,
      caloriesOut: 300,
      macros: { protein: 120, carbs: 200, fat: 70 },
    },
    {
      date: '2025-03-02',
      weight: 179,
      workouts: 'Ran 5km',
      caloriesIn: 2200,
      caloriesOut: 500,
      macros: { protein: 130, carbs: 250, fat: 80 },
    },
    {
      date: '2025-03-03',
      weight: 178.5,
      workouts: 'Yoga session + short run',
      caloriesIn: 2100,
      caloriesOut: 400,
      macros: { protein: 100, carbs: 220, fat: 60 },
    },
  ]);

  // For demonstration, we’ll display macros from the **most recent day**:
  const lastEntry = dailyData[dailyData.length - 1];

  // ========== CHART CONFIGS ==========

  // 1. Weight Over Time (Line Chart)
  const weightLineData = {
    labels: dailyData.map((entry) => entry.date),
    datasets: [
      {
        label: 'Weight (lbs)',
        data: dailyData.map((entry) => entry.weight),
        borderColor: 'rgba(75, 192, 192, 1)',
        backgroundColor: 'rgba(75, 192, 192, 0.2)',
        tension: 0.2,
        fill: true,
      },
    ],
  };
  const weightLineOptions = {
    responsive: true,
    maintainAspectRatio: false as const,
    plugins: {
      title: {
        display: true,
        text: 'Weight Over Time',
      },
      legend: {
        labels: {
          color: '#fff',
        },
      },
    },
    scales: {
      x: {
        ticks: { color: '#fff' },
      },
      y: {
        ticks: { color: '#fff' },
        beginAtZero: false,
      },
    },
  };

  // 2. Calories In vs Out (Bar Chart)
  const calsBarData = {
    labels: dailyData.map((entry) => entry.date),
    datasets: [
      {
        label: 'Calories In',
        data: dailyData.map((entry) => entry.caloriesIn),
        backgroundColor: 'rgba(54, 162, 235, 0.6)',
      },
      {
        label: 'Calories Out',
        data: dailyData.map((entry) => entry.caloriesOut),
        backgroundColor: 'rgba(255, 99, 132, 0.6)',
      },
    ],
  };
  const calsBarOptions = {
    responsive: true,
    maintainAspectRatio: false as const,
    plugins: {
      title: {
        display: true,
        text: 'Calories In vs. Calories Out',
      },
      legend: {
        labels: {
          color: '#fff',
        },
      },
    },
    scales: {
      x: {
        ticks: { color: '#fff' },
      },
      y: {
        ticks: { color: '#fff' },
        beginAtZero: true,
      },
    },
  };

  // 3. Nutrient Intake (Macros) - Doughnut Chart (most recent day)
  const macrosData = {
    labels: ['Protein', 'Carbs', 'Fat'],
    datasets: [
      {
        data: [lastEntry.macros.protein, lastEntry.macros.carbs, lastEntry.macros.fat],
        backgroundColor: [
          'rgba(54, 162, 235, 0.6)',   // Protein
          'rgba(255, 205, 86, 0.6)',   // Carbs
          'rgba(255, 99, 132, 0.6)',   // Fat
        ],
      },
    ],
  };
  const macrosOptions = {
    responsive: true,
    maintainAspectRatio: false as const,
    plugins: {
      title: {
        display: true,
        text: `Latest Day Macros (${lastEntry.date})`,
      },
      legend: {
        labels: {
          color: '#fff',
        },
      },
    },
  };

  // ========== RENDER ==========

  return (
    <div className="max-w-5xl mx-auto px-4 py-8 space-y-6 text-white">
      {/* Heading & Add Entry Button */}
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between">
        <h1 className="text-2xl font-bold mb-4 md:mb-0">Daily Dashboard</h1>
        <button
          className="px-4 py-2 bg-blue-600 hover:bg-blue-500 rounded transition font-semibold"
          onClick={() => alert('Open form or modal to add entries here!')}
        >
          Add Entry
        </button>
      </div>

      {/* Charts in a Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Weight Over Time (Line Chart) */}
        <div className="bg-[#2A2336] rounded-md p-4 shadow-md h-[350px]">
          <div className="relative w-full h-full">
            <Line data={weightLineData} options={weightLineOptions} />
          </div>
        </div>

        {/* Calories In vs Out (Bar Chart) */}
        <div className="bg-[#2A2336] rounded-md p-4 shadow-md h-[350px]">
          <div className="relative w-full h-full">
            <Bar data={calsBarData} options={calsBarOptions} />
          </div>
        </div>
      </div>

      {/* Macros & Workouts in another row */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Macros (Donut Chart) */}
        <div className="bg-[#2A2336] rounded-md p-4 shadow-md h-[350px]">
          <div className="relative w-full h-full">
            <Doughnut data={macrosData} options={macrosOptions} />
          </div>
        </div>

        {/* Recent Workouts */}
        <div className="bg-[#2A2336] rounded-md p-4 shadow-md">
          <h2 className="text-lg font-medium mb-4">Recent Workouts</h2>
          <ul className="space-y-4 max-h-64 overflow-auto pr-2">
            {dailyData.map((entry) => (
              <li
                key={entry.date}
                className="bg-[#1A1624] rounded-md p-3 shadow hover:shadow-lg transition-shadow"
              >
                <div className="flex items-center gap-2 mb-2">
                  <CalendarIcon className="h-5 w-5 text-blue-400" />
                  <span className="font-semibold">{entry.date}</span>
                </div>
                <p className="text-sm text-gray-300">{entry.workouts}</p>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}
